H.background();
const a = P.a, b = P.b;
const lo = Math.abs(a - b), hi = a + b;
const mid = (lo + hi) / 2, amp = hi * 0.7;
let c = mid + amp * Math.sin(t * 0.7);
if (c < 0.05) c = 0.05;
const valid = c > lo + 1e-9 && c < hi - 1e-9;
const cx = H.W / 2, baseY = 360;
const scale = 300 / Math.max(hi, 4);
const half = (c * scale) / 2;
const Lx = cx - half, Rx = cx + half;
let apex = null;
if (valid) {
  const x = (c * c + a * a - b * b) / (2 * c);
  const h2 = a * a - x * x;
  if (h2 > 0) {
    const h = Math.sqrt(h2);
    apex = { x: Lx + x * scale, y: baseY - h * scale };
  }
}
H.text("Triangle inequality: |a - b| < c < a + b", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Two sides force the third into a window; outside it, the triangle cannot close.", 24, 52, { color: H.colors.sub, size: 13 });
const nlY = 150, nlX0 = 60, nlX1 = H.W - 60;
const nmax = hi * 1.25 + 1;
const NX = vv => nlX0 + (vv / nmax) * (nlX1 - nlX0);
H.line(nlX0, nlY, nlX1, nlY, { color: H.colors.grid, width: 2 });
H.rect(NX(lo), nlY - 8, NX(hi) - NX(lo), 16, { fill: "rgba(63,185,80,0.35)", stroke: H.colors.good, width: 1, radius: 3 });
H.line(NX(lo), nlY - 16, NX(lo), nlY + 16, { color: H.colors.warn, width: 2 });
H.line(NX(hi), nlY - 16, NX(hi), nlY + 16, { color: H.colors.warn, width: 2 });
H.text("|a-b| = " + lo.toFixed(2), NX(lo), nlY + 32, { color: H.colors.sub, size: 12, align: "center" });
H.text("a+b = " + hi.toFixed(2), NX(hi), nlY + 32, { color: H.colors.sub, size: 12, align: "center" });
H.circle(NX(c), nlY, 7, { fill: valid ? H.colors.accent : H.colors.warn });
H.text("c = " + c.toFixed(2), NX(c), nlY - 24, { color: valid ? H.colors.accent : H.colors.warn, size: 13, align: "center", weight: 700 });
H.line(Lx, baseY, Rx, baseY, { color: H.colors.accent, width: 3 });
H.text("c", (Lx + Rx) / 2, baseY + 22, { color: H.colors.accent, size: 14, align: "center" });
if (apex) {
  H.path([[Lx, baseY], [apex.x, apex.y], [Rx, baseY]], { color: H.colors.ink, width: 3, fill: "rgba(110,168,254,0.12)", close: true });
  H.text("a = " + a.toFixed(1), (Lx + apex.x) / 2 - 18, (baseY + apex.y) / 2, { color: H.colors.violet, size: 13 });
  H.text("b = " + b.toFixed(1), (Rx + apex.x) / 2 + 4, (baseY + apex.y) / 2, { color: H.colors.violet, size: 13 });
} else {
  const ax = Lx + a * scale, bx = Rx - b * scale;
  H.line(Lx, baseY, ax, baseY - 1, { color: H.colors.violet, width: 3 });
  H.line(Rx, baseY, bx, baseY - 1, { color: H.colors.violet, width: 3 });
  H.text("a", (Lx + ax) / 2, baseY - 12, { color: H.colors.violet, size: 13, align: "center" });
  H.text("b", (Rx + bx) / 2, baseY - 12, { color: H.colors.violet, size: 13, align: "center" });
}
H.text(valid ? "VALID triangle" : "NOT a triangle", H.W / 2, 470, { color: valid ? H.colors.good : H.colors.warn, size: 16, align: "center", weight: 700 });
